import sys, os
from xml.dom import minidom

path = "unpacked/word/document.xml"
doc = minidom.parse(path)
body = doc.getElementsByTagName("w:body")[0]

def para_text(p):
    texts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild:
            texts.append(t.data)
    return "".join(texts)

def para_style(p):
    pPr = p.getElementsByTagName("w:pPr")
    if not pPr:
        return None
    st = pPr[0].getElementsByTagName("w:pStyle")
    if st and st[0].getAttribute("w:val"):
        return st[0].getAttribute("w:val")
    return None

idx = 0
for child in body.childNodes:
    if child.nodeType != child.ELEMENT_NODE:
        continue
    if child.tagName == "w:p":
        txt = para_text(child)
        style = para_style(child)
        print(f"P[{idx}] style={style!r} text={txt[:110]!r}")
    elif child.tagName == "w:tbl":
        print(f"P[{idx}] <TABLE>")
    elif child.tagName == "w:sectPr":
        print(f"P[{idx}] <SECTION PROPERTIES>")
    idx += 1

