import sys
sys.path.insert(0, ".codex/skills/docx")
from scripts.document import DocxXMLEditor

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

def text_of(p):
    parts = []
    for node in p.getElementsByTagNameNS(W, "t"):
        parts.append("".join(ch.data for ch in node.childNodes if ch.nodeType == ch.TEXT_NODE))
    for node in p.getElementsByTagNameNS(W, "delText"):
        parts.append("[DEL:" + "".join(ch.data for ch in node.childNodes if ch.nodeType == ch.TEXT_NODE) + "]")
    return "".join(parts)

def style_of(p):
    pPr = p.getElementsByTagNameNS(W, "pPr")
    if pPr:
        pStyle = pPr[0].getElementsByTagNameNS(W, "pStyle")
        if pStyle:
            return pStyle[0].getAttributeNS(W, "val")
    return None

editor = DocxXMLEditor("unpacked/word/document.xml")
body = editor.dom.getElementsByTagNameNS(W, "body")[0]
paras = body.getElementsByTagNameNS(W, "p")
print("TOTAL PARAGRAPHS:", len(paras))
for i, p in enumerate(paras):
    st = style_of(p)
    tx = text_of(p).strip()
    if st or tx:
        shown = tx if len(tx) <= 120 else tx[:120] + "..."
        print(f"[{i}] style={st} text={shown!r}")

