import os

TARGET = "quarterly_report.docx"

cwd = os.getcwd()
print("CWD:", cwd)
print("CWD_LISTING:", sorted(os.listdir(cwd)))

roots = [cwd, os.path.dirname(cwd)]
for extra in ["/workspace", "/mnt", "/tmp", "/home", "/root", "/data", "/app"]:
    if extra not in roots and os.path.isdir(extra):
        roots.append(extra)

prune = {".git", "node_modules", "__pycache__", ".cache", "venv", ".venv"}
hits = []
for root in roots:
    if not os.path.isdir(root):
        continue
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in prune]
        if TARGET in filenames:
            p = os.path.join(dirpath, TARGET)
            hits.append((p, os.path.getsize(p)))
        if len(hits) >= 20:
            break
    if len(hits) >= 20:
        break

print("HITS:")
for p, size in hits:
    print(p, size)
if not hits:
    print("NO_HITS")

from defusedxml import minidom

dom = minidom.parse("quarterly_report_unpacked/word/document.xml")
root = dom.documentElement
body = root.getElementsByTagName("w:body")[0]


def para_text(elem):
    out = []
    for node in elem.childNodes:
        if node.nodeType != node.ELEMENT_NODE:
            continue
        if node.tagName == "w:r":
            for t in node.getElementsByTagName("w:t"):
                if t.firstChild:
                    out.append(t.firstChild.data)
            for d in node.getElementsByTagName("w:delText"):
                if d.firstChild:
                    out.append("[DEL:" + d.firstChild.data + "]")
    return "".join(out)


def para_style(elem):
    ppr = elem.getElementsByTagName("w:pPr")
    if not ppr:
        return ""
    ps = ppr[0].getElementsByTagName("w:pStyle")
    if ps:
        return ps[0].getAttribute("w:val")
    return ""


print("=== TOP-LEVEL BODY CHILDREN ===")
idx = 0
for child in body.childNodes:
    if child.nodeType != child.ELEMENT_NODE:
        continue
    tag = child.tagName
    if tag == "w:p":
        txt = para_text(child)
        print(idx, "P", "style=" + para_style(child), repr(txt[:150]))
    elif tag == "w:tbl":
        rows = child.getElementsByTagName("w:tr")
        print(idx, "TABLE rows=", len(rows))
    elif tag == "w:sectPr":
        print(idx, "SECTPR")
    else:
        print(idx, tag)
    idx += 1

print()
print("=== STYLES USED (unique) ===")
styles = set()
for p in body.getElementsByTagName("w:p"):
    s = para_style(p)
    if s:
        styles.add(s)
print(sorted(styles))

# Check styles.xml for available heading styles
try:
    sdom = minidom.parse("quarterly_report_unpacked/word/styles.xml")
    avail = []
    for st in sdom.getElementsByTagName("w:style"):
        sid = st.getAttribute("w:styleId")
        nm = st.getElementsByTagName("w:name")
        nv = nm[0].getAttribute("w:val") if nm else ""
        avail.append((sid, nv))
    print()
    print("=== STYLES.XML ids ===")
    print(avail)
except Exception as e:
    print("styles read error:", e)

